package org.zhbot.skilling_special_attack;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;

import java.awt.*;

@ConfigGroup(SkillingSpecialAttackConfig.group)
public interface SkillingSpecialAttackConfig extends Config
{
	String group = "skilling-special-attack";

	@ConfigItem(
			keyName = "notifications",
			name = "Notifications",
			description = "Configures all notifications",
			position = 0
	)
	default Notification notification()
	{
		return Notification.ON;
	}

	@ConfigItem(
			keyName = "showNotificationPanel",
			name = "Show notification panel",
			description = "Shows the notification panel when available",
			position = 1
	)
	default boolean showNotificationPanel(){
		return true;
	}

	@ConfigItem(
			keyName = "shouldFlash",
			name = "Flash notification panel",
			description = "Flashes notification panel",
			position = 2
	)
	default boolean shouldFlash(){
		return true;
	}

	@ConfigItem(
			keyName = "notificationPanelColor1",
			name = "Color 1",
			description =  "First color for notification panel flash",
			position = 3
	)
	default Color notificationPanelColor1(){
		return Color.RED;
	}

	@ConfigItem(
			keyName = "notificationPanelColor2",
			name = "Color 2",
			description =  "Second color for notification panel flash",
			position = 4
	)
	default Color notificationPanelColor2(){
		return Color.GRAY;
	}
}

package org.zhbot.skilling_special_attack;

import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;

import javax.inject.Inject;
import java.awt.*;

public class SkillingSpecialAttackOverlay extends OverlayPanel {
    private final Client client;
    private final SkillingSpecialAttackConfig config;

    @Inject
    private SkillingSpecialAttackOverlay(Client client, SkillingSpecialAttackConfig config)
    {
        this.client = client;
        this.config = config;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        panelComponent.getChildren().add((LineComponent.builder())
                .left("Skilling special attack ready!")
                .build());

        if (config.shouldFlash()) {
            if (client.getGameCycle() % 40 >= 20)
            {
                panelComponent.setBackgroundColor(config.notificationPanelColor1());
            } else
            {
                panelComponent.setBackgroundColor(config.notificationPanelColor2());
            }
        } else {
            panelComponent.setBackgroundColor(config.notificationPanelColor1());
        }

        setPosition(OverlayPosition.ABOVE_CHATBOX_RIGHT);

        return panelComponent.render(graphics);
    }
}

package org.zhbot.skilling_special_attack;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.Notifier;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.Set;

@Slf4j
@PluginDescriptor(
	name = "Skilling Special Attack"
)
public class SkillingSpecialAttackPlugin extends Plugin
{
	private static final int MAX_SA_ENERGY = 1000;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SkillingSpecialAttackConfig config;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SkillingSpecialAttackOverlay overlay;

	private final Set<Integer> SkillingSpecWeaponIDs = Set.of(
			ItemID.LEAGUE_TRAILBLAZER_AXE,
			ItemID.LEAGUE_TRAILBLAZER_HARPOON,
			ItemID.LEAGUE_TRAILBLAZER_PICKAXE,
			ItemID.DRAGON_AXE,
			ItemID.DRAGON_AXE_2H,
			ItemID.TRAILBLAZER_AXE,
			ItemID.TRAILBLAZER_AXE_NO_INFERNAL,
			ItemID.INFERNAL_AXE,
			ItemID._3A_AXE,
			ItemID._3A_AXE_2H,
			ItemID.CRYSTAL_AXE,
			ItemID.CRYSTAL_AXE_INACTIVE,
			ItemID.CRYSTAL_AXE_2H,
			ItemID.CRYSTAL_AXE_2H_INACTIVE,
			ItemID.DRAGON_HARPOON,
			ItemID.INFERNAL_HARPOON,
			ItemID.CRYSTAL_HARPOON,
			ItemID.CRYSTAL_HARPOON_INACTIVE,
			ItemID.DRAGON_PICKAXE,
			ItemID.DRAGON_PICKAXE_PRETTY,
			ItemID.ZALCANO_PICKAXE,
			ItemID.TRAILBLAZER_PICKAXE,
			ItemID.TRAILBLAZER_PICKAXE_NO_INFERNAL,
			ItemID.INFERNAL_PICKAXE,
			ItemID._3A_PICKAXE,
			ItemID.CRYSTAL_PICKAXE,
			ItemID.CRYSTAL_PICKAXE_INACTIVE
	);

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(SkillingSpecialAttackConfig.group))
		{
			if (config.showNotificationPanel())
			{
				clientThread.invoke(() -> {
					if (client.getVarpValue(VarPlayerID.SA_ENERGY) == MAX_SA_ENERGY && checkEquipment())
						overlayManager.add(overlay);
				});
			}
			else
			{
				overlayManager.remove(overlay);
			}
		}
	}

	@Provides
	SkillingSpecialAttackConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SkillingSpecialAttackConfig.class);
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SA_ENERGY)
			return;

		if (event.getValue() != MAX_SA_ENERGY)
		{
			overlayManager.remove(overlay);
			return;
		}

		if (!checkEquipment())
			return;

		notifier.notify(config.notification(), "Skilling special attack now available.");
		if (config.showNotificationPanel())
			overlayManager.add(overlay);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() != InventoryID.WORN)
			return;

		if (checkEquipment())
		{
			if (config.showNotificationPanel() && client.getVarpValue(VarPlayerID.SA_ENERGY) == MAX_SA_ENERGY)
				overlayManager.add(overlay);
		}
		else
		{
			overlayManager.remove(overlay);
		}
	}

	private boolean checkEquipment()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
			return false;

		Item weapon = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null)
			return false;

        return SkillingSpecWeaponIDs.contains(weapon.getId());
    }
}

